  ra_guide_s3: 'Aggiungilo alla schermata home del telefono',
  ra_guide_s3_body: 'Su iPhone premi Condividi e poi Aggiungi a Home. Su Android è Chrome a proportelo. Da lì Xenon si apre con la sua icona, a tutto schermo, e lì funzionano il microfono e le notifiche.',
  ra_guide_s4: 'Accendi l\'indirizzo sicuro',
  ra_guide_s4_body: 'Dà a questo PC un nome tutto suo che funziona da ovunque, su una connessione cifrata. Usa Tailscale, che è gratis, e Xenon lo installa e ci accede per te. Non stai creando nessun account con Xenon.',
  ra_guide_s5: 'Attiva i certificati HTTPS nel tuo account Tailscale',
  ra_guide_s5_body: 'È l\'unico passaggio che Xenon non può fare al posto tuo. Apri la console di Tailscale, scendi fino a HTTPS Certificates e premi Enable. È gratis con qualsiasi piano. Poi torna qui: Xenon ha continuato ad aspettare.',
  ra_guide_s6: 'Installa Tailscale sul telefono, stesso account',
  ra_guide_s6_body: 'Scaricalo dall\'App Store o da Google Play, accedi con lo stesso account che hai appena usato e accendi il suo interruttore. È il passaggio che tutti dimenticano. Quando manca, il telefono dice che non riesce proprio ad aprire l\'indirizzo: non è rotto niente, quell\'indirizzo esiste solo dentro la tua rete.',
  ra_guide_s7: 'Abbina di nuovo il telefono sul nuovo indirizzo',
  ra_guide_s7_body: 'Premi Aggiungi dispositivo al passo 2 e inquadra di nuovo. Il browser lega l\'abbinamento all\'indirizzo su cui l\'hai fatto, quindi un telefono abbinato sull\'indirizzo di casa non è abbinato su quello sicuro. Da qui in poi ti serve solo il nuovo indirizzo, in casa e fuori.',
  ra_guide_done_title: 'La configurazione è finita',
  ra_guide_done_body: 'Il telefono è abbinato. Ultima cosa: Xenon deve continuare ad aprirsi anche su questo PC?',
  ra_guide_keep: 'Tienilo anche qui',
  ra_guide_hide: 'Nascondi Xenon su questo PC',
  ra_guide_hide_note: 'Nasconderlo fa sì che Xenon non si apra più su questo PC, nemmeno all\'avvio. Resta acceso in background, quindi il telefono continua a funzionare. Riporti indietro la finestra dall\'icona di Xenon vicino all\'orologio, oppure da Impostazioni, poi Schermo.',
  ra_guide_hide_browser: 'Questa è la dashboard dentro un browser, quindi non c\'è nessuna finestra da nascondere. Nell\'app Xenon puoi anche scegliere di non farla più aprire su questo PC.',
